from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    counts=Counter(v for row in grid for v in row)
    # Rare color object is a stamp. Its full shape is copied wherever the
    # same relative positions are all zero; existing stamp cells remain.
    color=min((v for v in counts if v != 0), key=lambda v: counts[v])
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==color]
    r0=min(r for r,c in pts); c0=min(c for r,c in pts)
    shape={(r-r0,c-c0) for r,c in pts}
    out=[row[:] for row in grid]
    s=shape
    sh=max(x for x,y in s)+1; sw=max(y for x,y in s)+1
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+x][c+y]==0 for x,y in s):
                for x,y in s: out[r+x][c+y]=color
    return out", "exit_code": 0, "error": null}
